import urllib.request
import urllib.error
import time
from typing import Optional


class RateLimitError(Exception):
    """Raised when the API returns HTTP 429 (Too Many Requests)."""
    pass


class ServerError(Exception):
    """Raised when the API returns an HTTP 5xx error after retry."""
    pass


class ClientError(Exception):
    """Raised when the API returns an HTTP 4xx error (except 429)."""
    pass


class ConnectionError(Exception):
    """Raised when a network error occurs after retry."""
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"

        def _do_request():
            req = urllib.request.Request(url)
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    raise RateLimitError(f"Rate limit exceeded: {status_code}")
                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}")
                elif 500 <= status_code < 600:
                    raise ServerError(f"Server error: {status_code}")
                else:
                    raise ClientError(f"Unexpected HTTP error: {status_code}")
            except urllib.error.URLError as e:
                raise ConnectionError(f"Network error: {e.reason}")

        return _do_request()

    def get(self, path: str) -> str:
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]
        retry_count = 0

        while True:
            try:
                return self._make_request(path)
            except RateLimitError:
                if retry_count < max_retries:
                    wait_time = backoff_times[retry_count]
                    time.sleep(wait_time)
                    retry_count += 1
                else:
                    raise
            except ServerError:
                if retry_count == 0:
                    time.sleep(1.0)
                    retry_count = 1
                    continue
                raise
            except ClientError:
                raise
            except ConnectionError:
                if retry_count == 0:
                    time.sleep(1.0)
                    retry_count = 1
                    continue
                raise
